--
-- Table structure for table `invoices`
--

DROP TABLE IF EXISTS `invoices`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `invoices` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `company_id` bigint(20) unsigned NOT NULL,
  `customer_id` bigint(20) unsigned DEFAULT NULL,
  `tipo_documento` varchar(2) NOT NULL,
  `serie` varchar(4) NOT NULL,
  `numero` int(11) NOT NULL,
  `fecha_emision` date NOT NULL,
  `hora_emision` time DEFAULT NULL,
  `fecha_vencimiento` date DEFAULT NULL,
  `moneda` varchar(3) NOT NULL DEFAULT 'PEN',
  `gravado` decimal(12,2) NOT NULL DEFAULT 0.00,
  `subtotal` decimal(12,2) NOT NULL DEFAULT 0.00,
  `exonerado` decimal(12,2) NOT NULL DEFAULT 0.00,
  `inafecto` decimal(12,2) NOT NULL DEFAULT 0.00,
  `exento` decimal(12,2) NOT NULL DEFAULT 0.00,
  `igv` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total` decimal(12,2) NOT NULL DEFAULT 0.00,
  `metodo_pago` varchar(50) DEFAULT NULL,
  `referencia_pago` varchar(100) DEFAULT NULL,
  `total_letras` varchar(255) DEFAULT NULL,
  `observaciones` text DEFAULT NULL,
  `codigo_hash` varchar(255) DEFAULT NULL,
  `pro51_external_id` varchar(255) DEFAULT NULL,
  `pro51_response` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `pro51_pdf_url` text DEFAULT NULL,
  `pro51_xml_url` text DEFAULT NULL,
  `pro51_cdr_url` text DEFAULT NULL,
  `pro51_ticket_url` text DEFAULT NULL,
  `pro51_sent_at` timestamp NULL DEFAULT NULL,
  `xml_path` varchar(255) DEFAULT NULL,
  `pdf_path` varchar(255) DEFAULT NULL,
  `cdr_path` varchar(255) DEFAULT NULL,
  `sunat_response` varchar(255) DEFAULT NULL,
  `sunat_estado` enum('PENDIENTE','ENVIADO','ACEPTADO','RECHAZADO','ANULADO') NOT NULL DEFAULT 'PENDIENTE',
  `sunat_ticket` varchar(255) DEFAULT NULL,
  `sunat_cdr` varchar(255) DEFAULT NULL,
  `sunat_serie` varchar(255) DEFAULT NULL,
  `sunat_numero` int(11) DEFAULT NULL,
  `sunat_fecha` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `credit_note_id` bigint(20) unsigned DEFAULT NULL,
  `docu_referencia` varchar(50) DEFAULT NULL,
  `order_source` varchar(10) DEFAULT NULL,
  `sunat_code` varchar(100) DEFAULT NULL,
  `sunat_description` varchar(255) DEFAULT NULL,
  `xml_firmado` longtext DEFAULT NULL,
  `exclude_from_totals` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `invoices_company_id_tipo_documento_serie_numero_unique` (`company_id`,`tipo_documento`,`serie`,`numero`),
  UNIQUE KEY `invoices_pro51_external_id_unique` (`pro51_external_id`),
  KEY `invoices_customer_id_foreign` (`customer_id`),
  KEY `invoices_credit_note_id_foreign` (`credit_note_id`),
  CONSTRAINT `invoices_company_id_foreign` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `invoices_credit_note_id_foreign` FOREIGN KEY (`credit_note_id`) REFERENCES `invoices` (`id`) ON DELETE SET NULL,
  CONSTRAINT `invoices_customer_id_foreign` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `invoices_chk_1` CHECK (json_valid(`pro51_response`))
) ENGINE=InnoDB AUTO_INCREMENT=366 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

